array<int> xs = [0, 1, 2, 3, 4];
array<int> part = array::slice(xs, 1, 3);   // a copy
xs.slice(3);                                 // xs itself becomes [3, 4]
print(to_json(part), " ", to_json(xs));

array<int> hp = [5, 0, 12, 0];
array<int> alive = array::filter(hp, h => h > 0);   // a copy
hp.filter(h => h > 10);                            // in place
print(to_json(alive), " ", to_json(hp));

array<int> xs = [3, 1, 2];
xs.sort();
print(to_json(xs));
xs.sort((a, b) => a > b);
print(to_json(xs));

array<int> xs = [1, 2, 3];
xs.map(x => x * 10);       // in place, keeps array<int>
print(to_json(xs));

map<string, int> stock = {"axe": 2, "bow": 0, "cup": 5};
map<string, int> big = map::filter(stock, (k, v) => v > 2);   // a copy
stock.filter((k, v) => v > 0);                                 // in place
print(to_json(big), " ", to_json(stock));

string s = "loud";
string t = s.to_upper();     // changes s and returns it
print(s, " ", t, " ", string::to_lower(t));

string s = "  hi  ";
s.trim();                        // in place
string t = "--x--";
t.trim("-");                     // a chosen character set
print("[", s, "] [", t, "] [", string::trim("  copy  "), "]");

array<int> a = [1];
array<int> b = a;
auto& r = a;
print(same_object(a, b), " ", same_object(a, r), " ", a == b);

class Orc { int hp = 7; }
Orc o;
reflect::set(o, "hp", 9);
print(reflect::get(o, "hp"));

class Orc { int hp = 7; void hit() { hp -= 1; } }
auto o = new Orc();
auto hit = reflect::bind(o, "hit");
hit();
hit();
print(o.hp);

class Orc { int hp = 7; Orc(int h) { hp = h; } }
var o = reflect::construct("Orc", 12);
print(o.hp);

binary::writer w;
w.uint16(513).int32(-2);
auto r = w.to_string().reader();
print(r.uint16(), " ", r.int32(), " ", r.at_end());

auto entry = binary::layout("id", binary::uint16, "hp", binary::int32);
binary::writer w;
w.pack(entry, {"id": 7, "hp": 120});
auto row = w.to_string().reader().unpack(entry);
print(row["id"], " ", row["hp"]);

array<int> xs = [1, 2];
xs.append([3, 4]);        // changes xs and returns it
print(to_json(xs));

array<int> xs = [1, 2, 3];
auto labels = array::map(xs, [](int x) -> string { return "#" + to_string(x); });
print(to_json(labels), " ", to_json(xs));
